const transliterations: Record<string, string> = { 'ß': 'ss', 'ẞ': 'ss', 'æ': 'ae', 'Æ': 'ae', 'œ': 'oe', 'Œ': 'oe', 'ø': 'o', 'Ø': 'o', 'ł': 'l', 'Ł': 'l', 'đ': 'd', 'Đ': 'd', 'ð': 'd', 'Ð': 'd', 'þ': 'th', 'Þ': 'th', 'ı': 'i', 'ĸ': 'k', 'ŧ': 't', 'Ŧ': 't' };
const normalized = title.replace(/[ßẞæÆœŒøØłŁđĐðÐþÞıĸŧŦ]/g, (letter) => transliterations[letter] ?? letter).normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
return normalized.replace(/&/g, ' and ').replace(/['’]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const special: Record<string, string> = {
  'ß': 'ss', 'ẞ': 'ss', 'æ': 'ae', 'Æ': 'ae', 'œ': 'oe', 'Œ': 'oe', 'ø': 'o', 'Ø': 'o', 'ł': 'l', 'Ł': 'l', 'đ': 'd', 'Đ': 'd', 'ð': 'd', 'Ð': 'd', 'þ': 'th', 'Þ': 'th', 'ı': 'i', 'İ': 'i', 'ŧ': 't', 'Ŧ': 't', 'ŋ': 'n', 'Ŋ': 'n'
};
let result = '';
let needsSeparator = false;
for (const char of title.toLowerCase()) {
  const spelling = special[char];
  const normalized = (spelling ?? char).normalize('NFKD').replace(/[\u0300-\u036f]/g, '');
  for (const ascii of normalized) {
    if (ascii >= 'a' && ascii <= 'z' || ascii >= '0' && ascii <= '9') {
      if (needsSeparator && result.length > 0) result += '_';
      result += ascii;
      needsSeparator = false;
    } else {
      needsSeparator = result.length > 0;
    }
  }
}
return result;
